from typing import Dict, Any, List
from azure.core.credentials import AzureKeyCredential
from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.ai.documentintelligence.models import PrebuiltModels

def get_content(field: Any) -> str | None:
    if field is None:
        return None
    return getattr(field, 'content', None)

def parse_money_or_quantity(s: str | None) -> float | None:
    if not s:
        return None
    cleaned = s.replace('$', '').replace('€', '').replace('£', '').replace('¥', '').replace(',', '').strip()
    try:
        return float(cleaned)
    except ValueError:
        return None

def extract_and_normalize_expenses(file_path: str, endpoint: str, api_key: str) -> Dict[str, Any]:
    with open(file_path, "rb") as f:
        document_content = f.read()

    client = DocumentIntelligenceClient(
        endpoint=endpoint,
        credential=AzureKeyCredential(api_key)
    )

    poller = client.begin_analyze_document(
        model_id=PrebuiltModels.RECEIPT,
        document=document_content
    )
    result = poller.result()

    if not result.documents:
        return {}

    document = result.documents[0]
    fields = document.fields

    normalized: Dict[str, Any] = {
        "vendor_name": get_content(fields.get("MerchantName")),
        "transaction_date": get_content(fields.get("TransactionDate")),
        "transaction_time": get_content(fields.get("TransactionTime")),
        "receipt_number": get_content(fields.get("ReceiptNumber")),
        "subtotal": parse_money_or_quantity(get_content(fields.get("Subtotal"))),
        "tax": parse_money_or_quantity(get_content(fields.get("Tax"))),
        "tip": parse_money_or_quantity(get_content(fields.get("Tip"))),
        "total_amount": parse_money_or_quantity(get_content(fields.get("Total"))),
        "currency_symbol": get_content(fields.get("CurrencySymbol")),
        "items": []
    }

    line_items_field = fields.get("LineItems")
    if line_items_field and hasattr(line_items_field, 'values') and line_items_field.values:
        for line_item in line_items_field.values:
            item_fields = line_item.fields
            item: Dict[str, Any] = {
                "description": get_content(item_fields.get("Name")),
                "quantity": parse_money_or_quantity(get_content(item_fields.get("Quantity"))),
                "unit_price": parse_money_or_quantity(get_content(item_fields.get("Price"))),
                "line_total": parse_money_or_quantity(get_content(item_fields.get("Total")))
            }
            normalized["items"].append(item)

    return normalized
